public class ArenaRenderer { private Texture2D _gridTexture; private Texture2D _borderTexture; public ArenaRenderer() { _gridTexture = new Texture2D(GraphicsDevice, GameConstants.WorldWidth, GameConstants.WorldHeight); _borderTexture = new Texture2D(GraphicsDevice, GameConstants.WorldWidth, GameConstants.WorldHeight); } public void Draw(SpriteBatch spriteBatch, Camera camera) { spriteBatch.Draw(_gridTexture, Vector2.Zero, Color.White); spriteBatch.Draw(_borderTexture, Vector2.Zero, Color.White); }